package com.coffeeshop.model;import java.time.LocalDate;public final class EmployeeModels{private EmployeeModels(){}public record Employee(long id,String number,String firstName,String lastName,String phone,String email,String jobTitle,LocalDate hireDate,LocalDate terminationDate,String status,boolean active,byte[]version,Long userId,String username,boolean userActive,String roles,byte[]userVersion){public Employee{version=version.clone();userVersion=userVersion==null?null:userVersion.clone();}@Override public byte[]version(){return version.clone();}@Override public byte[]userVersion(){return userVersion==null?null:userVersion.clone();}public String name(){return firstName+" "+lastName;}}public record Role(long id,String code,String name){@Override public String toString(){return name;}}}
